import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
        long w = Long.parseLong(input[0]);
        long m = Long.parseLong(input[1]);

        long[] sum = new long[105];
        long[] pw = new long[105];
        boolean[] answer = {false};

        long p = 1;
        int maxIdx = 0;
        for (int i = 0; i < 100; i++) {
            sum[i + 1] = sum[i] + p;
            pw[i] = p;
            p *= w;
            if (p > (1L << 40)) {
                maxIdx = i;
                break;
            }
        }

        recurse(0, m, maxIdx, sum, pw, answer);
        System.out.println(answer[0] ? "YES" : "NO");
    }

    static void recurse(long current, long target, int index, long[] sum, long[] pw, boolean[] answer) {
        if (answer[0]) return;
        if (current == target) {
            answer[0] = true;
            return;
        }
        long remainingSum = sum[index + 1];
        long powerVal = pw[index];

        if (current - remainingSum > target || current + remainingSum < target) {
            return;
        }

        if (current + sum[index] < target) {
            recurse(current + powerVal, target, index - 1, sum, pw, answer);
        } else if (current - sum[index] > target) {
            recurse(current - powerVal, target, index - 1, sum, pw, answer);
        } else {
            recurse(current, target, index - 1, sum, pw, answer);
        }
    }
}
