#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long w, m;
    std::string line;
    std::getline(std::cin, line);
    std::istringstream iss(line);
    iss >> w >> m;

    std::vector<long long> sum(105, 0);
    std::vector<long long> pw(105, 0);
    bool answer = false;

    long long p = 1;
    int maxIdx = 0;
    for (int i = 0; i < 100; i++) {
        sum[i + 1] = sum[i] + p;
        pw[i] = p;
        p *= w;
        if (p > (1LL << 40)) {
            maxIdx = i;
            break;
        }
    }

    std::function<void(long long, long long, int)> recurse = [&](long long current, long long target, int index) {
        if (answer) return;
        if (current == target) {
            answer = true;
            return;
        }
        long long remainingSum = sum[index + 1];
        long long powerVal = pw[index];

        if (current - remainingSum > target || current + remainingSum < target) {
            return;
        }

        if (current + sum[index] < target) {
            recurse(current + powerVal, target, index - 1);
        } else if (current - sum[index] > target) {
            recurse(current - powerVal, target, index - 1);
        } else {
            recurse(current, target, index - 1);
        }
    };

    recurse(0, m, maxIdx);
    std::cout << (answer ? "YES" : "NO") << "\n";

    return 0;
}
